INSERT IGNORE INTO page_section (page_key, section_key, area_code, title, body_html, sort_order) VALUES
  ('academic.academiccouncil', 'main', 'academic', 'MoM of Academic Council: text', '<p><strong>Updated Soon&#8230</strong></p>', 10),
  ('academic.admission', 'heading', 'academic', 'UG Admission: heading', '<h3 id="ctl00_ContentPlaceHolder1_h4_heading">Entrance Test</h3>', 10),
  ('academic.admission', 'entrance', 'academic', 'UG Admission: entrance test and first-year qualification', '<p>Admission in Katihar Engineering College (KEC) for four years\r\n                                                        B.Tech.\r\n                                                        course is made through Bihar Combined Entrance Competitive\r\n                                                        Examination (B.C.E.C.E.) conducted by Bihar Combined Entrance\r\n                                                        Competitive Examination Board. The candidates desirous of\r\n                                                        seeking\r\n                                                        Admission in KEC are advised to appear in competitive\r\n                                                        examination of\r\n                                                        B.C.E.C.E. The details for filling up the form for B.C.E.C.E.,\r\n                                                        fee\r\n                                                        structure, quota and other things is available in its prospectus\r\n                                                        as\r\n                                                        well as on the Website:\r\n                                                        <a\r\n                                                            href="http://bceceboard.bihar.gov.in/pdf_Pros/PROS_BC18.pdf">http://bceceboard.bihar.gov.in/pdf_Pros/PROS_BC18.pdf</a>\r\n                                                    <p> <a\r\n                                                            href="http://bceceboard.bihar.gov.in/">http://bceceboard.bihar.gov.in/</a>\r\n                                                    </p>\r\n                                                    </p>\r\n                                                    <p id="ctl00_ContentPlaceHolder1_h4_heading"><strong>Minimum\r\n                                                            Qualification for admission in first year of UG\r\n                                                            programme</strong></p>\r\n                                                    <div id="ctl00_ContentPlaceHolder1_div_1">The minimum academic\r\n                                                        qualification for admission through BCECE entrance examination\r\n                                                        is a\r\n                                                        pass in the final examination of the Intermediate, 10+2 system\r\n                                                        or\r\n                                                        its equivalent. Those appearing in the Intermediate final or\r\n                                                        equivalent examination may also appear in the entrance\r\n                                                        examination\r\n                                                        for consideration of provisional admission. All provisional\r\n                                                        admissions will stand cancelled, if proof of having passed the\r\n                                                        qualifying examination (Intermediate or equivalent) is not\r\n                                                        submitted\r\n                                                        to the institute at the time of counselling. If an applicant is\r\n                                                        found ineligible at a later date even after admission to the\r\n                                                        KEC,\r\n                                                        his/her admission will be cancelled.\r\n                                                        All admissions will be subject to verification of facts from the\r\n                                                        original certificates/documents of the candidates. The decision\r\n                                                        of\r\n                                                        the B.C.E.C.E. Board regarding eligibility of any applicant\r\n                                                        shall be\r\n                                                        final.\r\n\r\n                                                    </div>\r\n                                                    <p id="ctl00_ContentPlaceHolder1_h4_heading"><strong>Minimum\r\n                                                            Qualification for the direct admission in second year of UG\r\n                                                            programme</strong></p>', 20),
  ('academic.admission', 'lateral', 'academic', 'UG Admission: direct admission in second year', '(A) Passed Diploma\r\n                                                        examination\r\n                                                        with at least 45% marks (40% in case of candidates belonging to\r\n                                                        reserved category) in appropriate branch of Engineering and\r\n                                                        Technology.\r\n                                                        <p>(B) Passed B.Sc. Degree from a recognized University as\r\n                                                            defined\r\n                                                            by UGC, with at least 45% marks (40% in case of candidates\r\n                                                            belonging to reserved category) and passed 10+2 examination\r\n                                                            with\r\n                                                            Mathematics as a subject.\r\n                                                        <p>(C) Provided that the students belonging to B.Sc. Stream,\r\n                                                            shall\r\n                                                            clear the subjects Engineering Graphics / Engineering\r\n                                                            Drawing\r\n                                                            and Engineering Mechanics of the First year Engineering\r\n                                                            Programme along with the Second year subjects.\r\n                                                        <p>(D) Provided that the students belonging to B.Sc. Stream\r\n                                                            shall be\r\n                                                            considered only after filling the supernumerary seats in\r\n                                                            this\r\n                                                            category with students belonging to the Diploma stream', 30),
  ('academic.admission', 'qualifying', 'academic', 'UG Admission: qualifying examinations', '<p><strong>The list of qualifying examinations For\r\n                                                                    Engineering\r\n                                                                    Stream</strong></p>\r\n                                                            <ul>\r\n                                                                <li>Intermediate Examination, Bihar Intermediate\r\n                                                                    Education\r\n                                                                    Council\r\n                                                                </li>\r\n                                                                <li>The 10+2, Central Board of Secondary Education, New\r\n                                                                    Delhi\r\n                                                                </li>\r\n                                                                <li>The 10+2, Council for Indian School Certificate\r\n                                                                    Examination, New Delhi.\r\n                                                                </li>\r\n                                                                <li>The +2 level examination in the 10 +2 pattern of\r\n                                                                    examination of any recognized Central Board of\r\n                                                                    Secondary\r\n                                                                    Examination and Council for Indian School\r\n                                                                    Certificate\r\n                                                                    Examination, New Delhi.\r\n                                                                </li>\r\n                                                                <li>3 or 4 year diploma recognized by AICTE or a state\r\n                                                                    board\r\n                                                                    of technical education. with Physics, Chemistry\r\n                                                                    &amp;\r\n                                                                    Mathematics as combination.\r\n                                                                </li>\r\n                                                            </ul>\r\n\r\n                                                            <div data-animation="bounceInUp" data-animation-delay="0s">\r\n                                                                <div id="ctl00_ContentPlaceHolder1_div_2">\r\n                                                                    <strong>Residential</strong>\r\n                                                                </div>\r\n                                                            </div>', 40),
  ('academic.admission', 'residential', 'academic', 'UG Admission: residential rules', '<p class="text-lg font-medium">Only those\r\n                                                                            candidates\r\n                                                                            can get admission who are citizens of India\r\n                                                                            and:\r\n                                                                        </p>\r\n                                                                        <ul class="list-none pl-4 space-y-2">\r\n                                                                            <li\r\n                                                                                class="before:content-[''-''] before:mr-2">\r\n                                                                                Their parents are natives of Bihar.</li>\r\n                                                                            <li\r\n                                                                                class="before:content-[''-''] before:mr-2">\r\n                                                                                Their parents are domiciled in Bihar.\r\n                                                                            </li>\r\n                                                                            <li\r\n                                                                                class="before:content-[''-''] before:mr-2">\r\n                                                                                Their parents are registered refugees of\r\n                                                                                Bihar.</li>\r\n                                                                            <li\r\n                                                                                class="before:content-[''-''] before:mr-2">\r\n                                                                                Their parents are natives of other\r\n                                                                                states\r\n                                                                                but employees of Govt. of Bihar.</li>\r\n                                                                        </ul>\r\n\r\n                                                                        <p class="text-xl font-semibold mt-4">List of\r\n                                                                            courses offered at KEC:</p>', 50),
  ('academic.antiragging', 'main', 'academic', 'Anti Ragging: text', '<p><strong>Updated Soon&#8230</strong></p>', 10),
  ('academic.attendance', 'main', 'exam', 'Attendance: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('academic.calender', 'main', 'exam', 'Academic Calender: links', '<ul class="list-disc pl-5 space-y-4">\r\n\r\n                        <li class="flex items-center hover:bg-blue-50 p-2 rounded transition duration-300 ease-in-out">\r\n                            <div class="flex-shrink-0">\r\n                                <i class="fa fa-calendar-alt text-blue-600 mr-2"></i>\r\n                            </div>\r\n                            <p>\r\n                                <span class="font-semibold">Bihar Engineering University Calendar:</span>\r\n                                <a href="http://beu-bih.ac.in/BEUP/Academic_Calendar.aspx" target="_blank" class="text-blue-600 hover:underline">Download</a>\r\n                            </p>\r\n                        </li>\r\n                    </ul>', 10),
  ('academic.mentors', 'main', 'academic', 'Mentors: text', '<p><strong>Updated Soon&#8230</strong></p>', 10),
  ('academic.notice', 'main', 'academic', 'Notice: text', '<p><strong>Updated Soon&#8230</strong></p>', 10),
  ('academic.paymenttutorial', 'main', 'fees', 'Fee payment tutorial: steps', '<h3 class="text-3xl font-bold mb-6 text-gray-800">Steps To Be Followed For Fee Payment:</h3>\r\n                        <div class="text-lg space-y-6 text-gray-700">\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 1:</strong> Open any browser.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 2:</strong> Go to the link <strong>onlinesbi.com/sbicollect</strong>. A page of "terms" will be opened.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 3:</strong> Tick the checkbox (acceptance of terms and conditions) and click on <strong>proceed</strong>. A new page will open.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 4:</strong> Select your <strong>State of Corporate/Institution</strong> (i.e., Bihar) and <strong>Type of Corporate/Institution</strong> (i.e., Educational Institutions), then click on <strong>Go</strong>. A new page will open.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 5:</strong> Select your <strong>Educational Institutions Name</strong> (i.e., Katihar Engineering College) and submit. A new page will open with the logo of Katihar Engineering College.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 6:</strong> Select <strong>Payment Category</strong> (i.e., either fees or fine depending upon what you are paying for).</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 7:</strong> Enter your details: Your Name, Registration no., Branch, Category, Email Id, Year/Semester, and fees (corresponding to the fee column).</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 8:</strong> Enter your Name, Date of Birth/Incorporation, Mobile no., Email Id, and the text shown in the image for banking, then <strong>Submit</strong>.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 9:</strong> A page with the details you entered will appear. Check the details carefully, and if correct, <strong>Submit</strong>.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 10:</strong> A page with several payment modes will open. Select the payment mode you prefer and complete the payment.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Step 11:</strong> After completing the payment, you can download the e-Receipt of payment.</p>\r\n                            <p class="bg-blue-100 p-3 rounded-md"><strong>Or you can also download the PDF containing screenshots of the steps for fee payment:</strong> <a href="/jsp/facilities/payment.pdf" target="_blank" class="text-blue-600 hover:underline">Click here to download</a></p>\r\n\r\n                </div>', 10),
  ('academic.regulations', 'main', 'academic', 'Academic Regulations: document', '<p>\r\n\r\n                    <div>\r\n                        <object data="/jsp/academic/regulation.pdf" type="application/pdf" width="700" height="1000">\r\n                            <embed src="/jsp/academic/regulation.pdf" type="application/pdf">\r\n                        </object>\r\n                    </div>\r\n                    </p>', 10),
  ('academic.rules', 'main', 'academic', 'Rules: text', '<p><strong>Updated Soon &#8230</strong></p>', 10),
  ('academic.syllabus', 'main', 'exam', 'Syllabus: links', '<p><code></p>\r\n                    <li>New Course Curriculum for Engineering & Technology for 1st & 2nd Semester based on AICTE Model Cirriculum to be followed from Session 2018-19 onwards <a href="http://akubihar.ac.in/Academics/Docs/NEW_CURRICULUM_ENGINEERING_TECHNOLOGY.pdf"\r\n                                                                                                                                                                                 rel="attachment wp-att-2593"> Download</a><br/></li>\r\n               <li>Revised B.tech Syllabus<a href="http://akubihar.ac.in/Academics/Docs/revised%20B%20tech%2019-02-11(revised).pdf">Download</a></li>', 10),
  ('academic.universityresults', 'main', 'exam', 'University Results: text', '<p class="text-center text-lg font-semibold text-gray-700">\r\n                   <strong>Updated Soon&#8230</strong>\r\n               </p>', 10);
